from jsonb_array_elements($j$[["rv_notice_not_procurement","notice_type","Job ads and career postings are not procurements","Job postings, hiring notices and career pages are not solicitations. Reject them as non-procurement content.","reject_not_a_procurement",true,90,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger"},["job posting","job opening","job opportunity","jobs in","now hiring","we're hiring","career opportunity","careers at","/careers","employment opportunity","apply now","submit resume","send resume","salary","hourly pay","per hour","full-time position","part-time position","position available","open position","staffing job","travel nurse","nurse job","ambulance job","emt job","paramedic job","rn job","job advertisement","job vacancy"],"ontology.HARD_REJECT_TERMS + routes/opportunities.ts.HARD_REJECT_SIGNALS","Carried from code. Note: 'needed', ' hiring ', 'seaborn' from the route gate are deliberately NOT migrated (see report)."],["rv_notice_post_award","notice_status","Award notices and post-award documents are not open opportunities","Award notices, bid tabulations, executed contracts, purchase orders, modifications and commentary pages are not open solicitations.","reject_post_award_notice",true,90,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger"},["contract awarded","award notice","awarded to","selected vendor","notice of award","intent to award","sole source award","bid tabulation","executed contract","purchase order","meeting agenda","generic contract list","procurement commentary","blog post","unrelated news article","contract modification","delivery order","task order modification","closed solicitation","cancelled solicitation"],"ontology.HARD_REJECT_TERMS + routes/opportunities.ts.HARD_REJECT_SIGNALS","Award/closed STATUS is also detected by the data-quality layer (opportunityQuality / opportunityExpiration). This rule only covers text-based notice-type rejection."],["rv_out_of_scope_health_it","service_scope","Health IT platforms are out of scope","Electronic health record, EMR, hospital information and telehealth/telemedicine software purchases are not Occu-Med services.","reject_as_out_of_scope",true,85,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger"},["electronic health record","ehr implementation","emr system","telehealth platform","telemedicine software","hospital information"],"ontology.HARD_REJECT_TERMS + routes/opportunities.ts.HARD_REJECT_SIGNALS",""],["rv_out_of_scope_non_occupational","service_scope","Non-occupational health and facility services are out of scope","Health insurance and pharmacy benefits, veterinary/animal health, pest control, janitorial, landscaping, and food/nutrition programs are not Occu-Med services.","reject_as_out_of_scope",true,85,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger"},["pharmacy benefits","health insurance","health benefits","veterinary","animal health","pest control","janitorial","landscaping","food service","meal delivery","nutrition program","wic program","school lunch","head start nutrition"],"ontology.HARD_REJECT_TERMS + routes/opportunities.ts.HARD_REJECT_SIGNALS",""],["rv_non_medical_primary_scope","service_scope","Physical/IT work named in the title is not an Occu-Med purchase","When the title describes physical, facilities or IT work and names no Occu-Med service, medical wording elsewhere in the notice is contract boilerplate, not the thing being purchased.","reject_when_title_scope_non_medical",true,88,{"applies_to":["opportunity_research","rfp_search"],"match":"title_any_trigger","rescued_by":"title_contains_service_term"},["corrosion","repaint","painting","roofing","paving","resurfacing","hvac","chillers","plumbing","elevators","snow removal","janitorial","custodial","landscaping","grounds maintenance","construction","renovation","demolition","abatement","installation of","repair of","repairs to","help desk","software development","network infrastructure","cabling","fencing","parking garage","surveillance cameras","toilets","weapons"],"relevance.ts.NON_MEDICAL_PRIMARY_SCOPE_RE + structuredOpportunityJudge prompt (surveillance cameras, toilets, weapons)",""],["rv_cond_ohs_safety_only","service_scope","Safety consulting/training without clinical delivery","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Safety consulting/training without clinical delivery.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["examination","physical","surveillance","medical clearance","audiometry","spirometry","drug testing","vaccination","clinical services"],"penalty":25},["safety consulting","construction safety","industrial hygiene only","environmental health and safety consulting","policy development","safety training","OHS management system"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.ohs_safety_only",""],["rv_cond_background_only","service_scope","Background screening without medical/testing scope","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Background screening without medical/testing scope.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["physical","medical","drug","alcohol","TB","audiogram","fitness","health assessment","laboratory"],"penalty":45},["background checks","fingerprinting","criminal history","employment verification","credential verification","education verification","motor vehicle records","I-9","E-Verify"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.background_only",""],["rv_cond_drug_adjacent","service_scope","Drug testing adjacent non-workforce context","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Drug testing adjacent non-workforce context.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["employee","applicant","candidate","workforce","workplace","DOT","safety-sensitive","pre-employment","post-accident","MRO","collection site","employer","personnel"],"penalty":25},["probation testing","court-ordered testing","treatment monitoring","drug-testing kits","laboratory supplies","forensic toxicology","student-athlete testing","pharmaceutical research","preclinical drug screening"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.drug_adjacent",""],["rv_cond_employee_benefits","service_scope","Benefits/insurance instead of clinical employee medical services","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Benefits/insurance instead of clinical employee medical services.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["examination","clinical","testing","surveillance","vaccination","medical clearance","occupational medicine"],"penalty":45},["health insurance","benefits administration","wellness incentives","population-health platform","EAP","pharmacy benefits","claims administration"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.employee_benefits",""],["rv_cond_medical_screening_nonworkforce","service_scope","Non-workforce medical screening","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Non-workforce medical screening.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["workforce","employment","occupational","deployment","public-safety","contractor personnel"],"penalty":25},["patient screening","cancer screening","community-health screening","research-subject screening","pharmaceutical clinical-trial screening"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.medical_screening_nonworkforce",""],["rv_cond_incidental_requirement","service_scope","Incidental contractor compliance requirement","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Incidental contractor compliance requirement.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["purchased deliverable","scope item","line item","vendor shall provide","testing services","collection services"],"penalty":45},["contractor must maintain","drug-testing policy","maintain a drug testing policy","employees assigned to this contract must pass"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.incidental_requirement",""],["rv_cond_supplies_only","service_scope","Equipment/supplies rather than medical service delivery","Treat as out of scope unless the notice also contains evidence of an actual Occu-Med service (see rescue terms). Equipment/supplies rather than medical service delivery.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["services","vendor shall provide testing","medical evaluation","program administration"],"penalty":25},["drug-testing kits","laboratory supplies","fit testing system","equipment only","purchase of equipment","test kits"],"ontology.CONDITIONAL_NEGATIVE_GROUPS.supplies_only",""],["rv_staffing_labor_supply","service_scope","Staffing and labor-supply procurements are out of scope","Staffing is out of scope for Occu-Med. Reject when staffing, clinical labor supply, locum services or ambulance operations is the purchased service. Words such as nurse, EMT, paramedic, firefighter or first responder do not trigger rejection when they identify the workforce receiving occupational-health services.","reject_as_out_of_scope",true,90,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","not_triggered_by_workforce_terms":["nurse","registered nurse","EMT","paramedic","firefighter","first responder"]},["nurse staffing","registered nurse staffing","lpn staffing","lvn staffing","emt staffing","paramedic staffing","ems staffing","medical staffing","clinical staffing","health-unit staffing","physician staffing","provider staffing","staff augmentation","temporary staffing","contract staffing","staffing services","per diem staff","locum","locum tenens","ambulance services","ambulance operations","ambulance transport","patient transport"],"routes/opportunities.ts.HARD_REJECT_SIGNALS (staffing/ambulance subset) + owner decision 2026-10-03","Owner decision: staffing stays excluded when it is the purchased service; no conditional/rescue path. Bare role words are intentionally NOT triggers."],["rv_cond_treatment_plan_admin","service_scope","Clinical treatment, pharmacy and plan administration without occupational exam scope","Patient treatment, pharmacy, cannabis and plan/claims administration are out of scope. Per Occu-Med policy an unlisted service is not automatically excluded, so these terms reject only when the notice has no occupational-examination or workforce-medical evidence (see rescue terms). Staffing is handled by rv_staffing_labor_supply.","conditional_reject_unless_service_evidence",false,75,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger","requires_one_of":["examination","physical","screening","surveillance","fitness for duty","medical evaluation","medical clearance","audiometric","spirometry","drug testing","vaccination","occupational health","employee health"],"penalty":45},["pharmacy","pharmaceutical","marijuana","cannabis","dispensary","phlebotomist","perfusion","ray tech","x-ray tech","radiology technologist","mri tech","ct tech","sonographer","ultrasound technologist","dental assistant","dental hygienist","dental care","mental health therapy","behavioral health treatment","substance abuse treatment","addiction treatment","detox program","psychiatric","psychotherapy","counseling services","crisis intervention","suicide prevention","childrens mental health","children's mental health","hmo","health plan","insurance enrollment","cobra administration","benefits administration","medical claims","claims data"],"routes/opportunities.ts.HARD_REJECT_SIGNALS","Non-staffing remainder of the route gate's treatment list, conditional because Neon policy 'unlisted_service_is_not_excluded' and capabilities (CDT dental exams, psychological assessment, venipuncture) conflict with an unconditional reject."],["rv_benefit_adjudication","service_scope","Benefit/disability adjudication and consultant panels are out of scope","Disability adjudication, benefit determination and medical-consultant panel work is claims/benefit adjudication, not employment fitness-for-duty. Consistent with the workers' compensation exclusion and IME policy.","reject_as_out_of_scope",true,85,{"applies_to":["opportunity_research","rfp_search"],"match":"any_trigger"},["disability adjudication","disability determination","social security disability","regional medical consultant","medical consultant","ime panel"],"routes/opportunities.ts.HARD_REJECT_SIGNALS",""],["rv_program_surveillance_lead_asbestos_silica","program_combination","Medical surveillance for lead/asbestos/silica","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["medical surveillance"],["lead","asbestos","silica"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_hearing_conservation_audiometry","program_combination","Hearing conservation with audiometric testing","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["hearing conservation"],["audiometric testing","audiogram"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_respiratory_medical_clearance","program_combination","Respiratory protection with medical evaluation/clearance/fit testing","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["respiratory protection","respirator"],["medical evaluation","medical clearance","fit testing"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_nfpa_1582_exam","program_combination","NFPA 1582 with medical examination/physical","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["NFPA 1582"],["medical examination","physical"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_dot_part_40_collection","program_combination","DOT Part 40 with collection/MRO/BAT","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["DOT Part 40","49 CFR Part 40"],["collection","MRO","BAT"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_centcom_medical_screening","program_combination","CENTCOM with medical screening/vaccination","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["CENTCOM"],["medical screening","vaccination"]]},[],"relevance.ts.regulatoryProgram",""],["rv_program_job_functions_medical_exam","program_combination","Essential job functions with medical examination/evaluation","A notice that contains evidence from every group below is a high-specificity Occu-Med program even without a literal service phrase.","accept_program_combination",false,80,{"applies_to":["opportunity_research","rfp_search"],"all_of":[["essential job functions"],["medical examination","medical evaluation"]]},[],"relevance.ts.regulatoryProgram",""],["rv_cond_unrelated_procurement","service_scope","Unrelated technology, defense-materiel and fleet purchases","Satellite/Starlink, software licensing, IT, cybersecurity, ammunition and vehicle-maintenance purchases are not Occu-Med scope unless the notice also contains evidence of an actual Occu-Med service.","conditional_reject_unless_service_evidence",false,70,{"applies_to":["forecast","recompete","opportunity_research"],"match":"any_trigger","requires_one_of":["examination","physical","screening","surveillance","fitness for duty","medical evaluation","medical clearance","audiometric","spirometry","drug testing","vaccination","occupational health","employee health"],"penalties":{"starlink":55,"satellite":35,"software license":35,"information technology":30,"cybersecurity":35,"ammunition":45,"vehicle maintenance":35}},["starlink","satellite","software license","information technology","cybersecurity","ammunition","vehicle maintenance"],"govconIntelligence.ts.NEGATIVE_TERMS","Per-term penalties preserved in scope.penalties. weapons/construction/janitorial/landscaping/food service/veterinary from the same list are already covered by other rules."],["rv_commodity_raw_material_supply","service_scope","Commodity and raw-material purchases are not Occu-Med scope","Bulk commodity, raw-material, fuel, metals and spare-parts purchases are not Occu-Med services. Applies to the notice title; a title that names an Occu-Med service term rescues it. Equipment-only purchases are covered by rv_cond_supplies_only.","reject_when_title_scope_non_medical",true,88,{"applies_to":["opportunity_research","rfp_search"],"match":"title_any_trigger","rescued_by":"title_contains_service_term"},["raw material","raw materials","bulk commodity","commodity purchase","steel","aluminum","copper","lumber","fuel","diesel","gasoline","asphalt","gravel","aggregate","cement","fertilizer","grain","resin","scrap metal","spare parts","replacement parts","pipe and fittings"],"NEW (not from code): owner decision 2026-10-03 to make commodity/equipment-supply rejection a canonical Neon rule","Companion to agent policy rfp_commodity_and_equipment_supply. Title-scoped so a clinical notice that merely mentions fuel or steel is unaffected."]]$j$::jsonb) e;
